/* Calculator page script body: invoked as new Function('root', 'bridge', source). */
const expressionEl = root.querySelector('.calc-expression');
const resultEl = root.querySelector('.calc-result');
const statusEl = root.querySelector('.calc-status');
const historyEl = root.querySelector('.calc-history');
if (!expressionEl || !resultEl || !statusEl || !historyEl) return () => {};

const STORAGE_KEY = 'codex-studio-calculator-history-v1';
const MAX_HISTORY = 12;
let expression = '';
let justEvaluated = false;
let history = [];

function readHistory() {
  try {
    const parsed = JSON.parse(window.localStorage.getItem(STORAGE_KEY) || '[]');
    if (Array.isArray(parsed)) history = parsed.filter(x => x && typeof x.expr === 'string' && typeof x.value === 'number' && Number.isFinite(x.value)).slice(0, MAX_HISTORY);
  } catch (_) { history = []; }
}
function saveHistory() {
  try { window.localStorage.setItem(STORAGE_KEY, JSON.stringify(history.slice(0, MAX_HISTORY))); } catch (_) {}
}
function formatNumber(n) {
  if (!Number.isFinite(n)) throw new Error('结果超出可计算范围');
  if (Object.is(n, -0)) n = 0;
  // Round display noise while retaining substantially more precision than users can enter.
  return String(Number(n.toPrecision(12)));
}
function showStatus(s = '') { statusEl.textContent = s; }
function displayExpression(s) { return s.replace(/\*/g, '×').replace(/\//g, '÷').replace(/-/g, '−'); }
function render() {
  expressionEl.textContent = displayExpression(expression) || ' ';
  if (!resultEl.textContent) resultEl.textContent = '0';
}
function tokenize(input) {
  const out = [];
  let i = 0;
  while (i < input.length) {
    if (/\s/.test(input[i])) { i++; continue; }
    const tail = input.slice(i);
    const m = tail.match(/^(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?/);
    if (m) { const n = Number(m[0]); if (!Number.isFinite(n)) throw new Error('数字超出范围'); out.push({ type: 'num', value: n }); i += m[0].length; continue; }
    if ('+-*/()'.includes(input[i])) { out.push({ type: input[i], value: input[i] }); i++; continue; }
    throw new Error('表达式中有无法识别的字符');
  }
  return out;
}
function calculate(input) {
  const ts = tokenize(input); let p = 0;
  function primary() {
    const t = ts[p++];
    if (!t) throw new Error('表达式不完整');
    if (t.type === 'num') return t.value;
    if (t.type === '+' || t.type === '-') { const v = primary(); return t.type === '-' ? -v : v; }
    if (t.type === '(') { const v = addSub(); if (!ts[p] || ts[p++].type !== ')') throw new Error('缺少右括号'); return v; }
    throw new Error('表达式不完整');
  }
  function mulDiv() {
    let v = primary();
    while (ts[p] && (ts[p].type === '*' || ts[p].type === '/')) {
      const op = ts[p++].type, r = primary();
      if (op === '/' && r === 0) throw new Error('不能除以零');
      v = op === '*' ? v * r : v / r;
      if (!Number.isFinite(v)) throw new Error('结果超出可计算范围');
    }
    return v;
  }
  function addSub() {
    let v = mulDiv();
    while (ts[p] && (ts[p].type === '+' || ts[p].type === '-')) {
      const op = ts[p++].type, r = mulDiv(); v = op === '+' ? v + r : v - r;
      if (!Number.isFinite(v)) throw new Error('结果超出可计算范围');
    }
    return v;
  }
  if (!ts.length) throw new Error('请输入算式');
  const value = addSub(); if (p !== ts.length) throw new Error('表达式格式不正确'); return value;
}
function updatePreview() {
  expressionEl.textContent = displayExpression(expression) || ' ';
  if (!expression) { resultEl.textContent = '0'; return; }
  try { resultEl.textContent = formatNumber(calculate(expression)); showStatus(''); }
  catch (e) { if (['不能除以零','结果超出可计算范围','数字超出范围'].includes(e.message)) { resultEl.textContent = '—'; showStatus(e.message); } else { resultEl.textContent = '…'; showStatus(''); } }
}
function commit() {
  if (!expression.trim()) return;
  try {
    const value = calculate(expression), shown = formatNumber(value);
    history.unshift({ expr: expression, value, shown }); history = history.slice(0, MAX_HISTORY); saveHistory();
    resultEl.textContent = shown; showStatus(''); expression = String(value); justEvaluated = true; renderHistory();
  } catch (e) { resultEl.textContent = '错误'; showStatus(e.message); }
}
function applyUnary(action) {
  // Unary operations modify just the trailing operand, preserving the arithmetic prefix.
  const numberMatch = expression.match(/(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$/);
  if (!numberMatch) {
    if (action === 'sign') { expression += '-'; justEvaluated = false; updatePreview(); return; }
    showStatus('请先输入操作数'); return;
  }
  const numberStart = expression.length - numberMatch[0].length;
  let operandStart = numberStart;
  while (operandStart > 0 && /[+-]/.test(expression[operandStart - 1]) && (operandStart - 1 === 0 || /[+*/(-]/.test(expression[operandStart - 2]))) operandStart--;
  const prefix = expression.slice(0, operandStart), base = calculate(expression.slice(operandStart));
  if (!Number.isFinite(base)) { showStatus('数字超出范围'); return; }
  let value;
  if (action === 'sign') value = -base;
  else if (action === 'percent') value = base / 100;
  else if (action === 'sqrt') { if (base < 0) { showStatus('负数不能开平方'); return; } value = Math.sqrt(base); }
  else if (action === 'square') value = base * base;
  else if (action === 'reciprocal') { if (base === 0) { showStatus('零没有倒数'); return; } value = 1 / base; }
  if (!Number.isFinite(value)) { showStatus('结果超出可计算范围'); return; }
  expression = prefix + String(value); resultEl.textContent = formatNumber(value); expressionEl.textContent = displayExpression(expression); justEvaluated = false; showStatus('');
}
function clearAll() { expression = ''; justEvaluated = false; resultEl.textContent = '0'; showStatus(''); render(); }
function appendKey(key) {
  showStatus('');
  if (key === 'clear') { clearAll(); return; }
  if (key === 'backspace') { if (justEvaluated) { clearAll(); return; } expression = expression.slice(0, -1); justEvaluated = false; updatePreview(); return; }
  if (key === '=') { commit(); return; }
  if (['sign','percent','sqrt','square','reciprocal'].includes(key)) { applyUnary(key); return; }
  if (!/^(?:\d|\.|[+*/-])$/.test(key)) return;
  if (justEvaluated) { if ((/^\d$|^\.$/.test(key)) && !expression.endsWith('-')) expression = ''; justEvaluated = false; }
  if (['+','-','*','/'].includes(key) && /[+*/-]$/.test(expression)) {
    if (key === '-' && !expression.endsWith('-')) { expression += key; updatePreview(); return; }
    if (expression.endsWith('-') && expression.length > 1 && /[+*/]/.test(expression.slice(-2, -1))) {
      if (key === '-') return;
      expression = expression.slice(0, -2) + key; updatePreview(); return;
    }
    expression = expression.slice(0, -1) + key; updatePreview(); return;
  }
  if (key === '.') {
    const tail = expression.match(/(?:^|[+*/(\-])([^+*/()\-]*)$/);
    if (tail && tail[1].includes('.')) return;
    if (!expression || /[+*/(\-]$/.test(expression)) expression += '0';
  }
  expression += key; updatePreview();
}
function renderHistory() {
  historyEl.textContent = '';
  history.forEach((item, index) => {
    const row = document.createElement('button'); row.type = 'button'; row.className = 'calc-history-item'; row.dataset.historyIndex = String(index);
    const exprSpan = document.createElement('span'); exprSpan.textContent = displayExpression(item.expr) + ' =';
    const valueSpan = document.createElement('span'); valueSpan.textContent = formatNumber(item.value);
    row.appendChild(exprSpan); row.appendChild(valueSpan); historyEl.appendChild(row);
  });
}
readHistory(); renderHistory(); render(); updatePreview();
function onClick(event) {
  const clearHistory = event.target.closest('[data-action="clear-history"]');
  if (clearHistory && root.contains(clearHistory)) { history = []; saveHistory(); renderHistory(); showStatus('历史记录已清空'); return; }
  const hist = event.target.closest('[data-history-index]');
  if (hist && root.contains(hist)) { const item = history[Number(hist.dataset.historyIndex)]; if (item) { expression = String(item.value); resultEl.textContent = formatNumber(item.value); expressionEl.textContent = displayExpression(item.expr); justEvaluated = true; showStatus(''); } return; }
  const button = event.target.closest('[data-key]');
  if (button && root.contains(button)) appendKey(button.dataset.key);
}
function onKeydown(event) {
  if (event.ctrlKey || event.metaKey || event.altKey) return;
  const target = event.target;
  if (target && (target.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(target.tagName))) return;
  if (event.key === 'Escape') { event.preventDefault(); clearAll(); }
  else if (event.key === 'Enter' || event.key === '=') { event.preventDefault(); commit(); }
  else if (event.key === 'Backspace') { event.preventDefault(); appendKey('backspace'); }
  else if (/^\d$/.test(event.key) || ['.','+','-','*','/'].includes(event.key)) { event.preventDefault(); appendKey(event.key); }
}
root.addEventListener('click', onClick);
window.addEventListener('keydown', onKeydown);
return () => { root.removeEventListener('click', onClick); window.removeEventListener('keydown', onKeydown); };
